sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Safely retrieve field values regardless of u_ prefix variations
    var toolSysId = current.getValue('u_tool') || current.getValue('tool');
    var addedCyclesVal = current.getValue('u_cycles_added') || current.getValue('cycles_added');

    if (!toolSysId || !addedCyclesVal) {
        gs.addErrorMessage("ToolGuard Sync Warning: Missing Tool Reference or Cycles Added value.");
        return;
    }

    var addedCycles = parseInt(addedCyclesVal, 10);

    // Query the master Tool record
    var toolGr = new GlideRecord('x_snc_toolguard_ai_tool');
    if (toolGr.get(toolSysId)) {

        // Fetch existing cycle count
        var currentCyclesVal = toolGr.getValue('u_current_cycles') || toolGr.getValue('current_cycles') || '0';
        var currentCycles = parseInt(currentCyclesVal, 10);
        var newTotal = currentCycles + addedCycles;

        // Set updated cycle count on Tool record
        if (toolGr.isValidField('u_current_cycles')) {
            toolGr.setValue('u_current_cycles', newTotal);
        } else {
            toolGr.setValue('current_cycles', newTotal);
        }

        // Fetch lifecycle limit and evaluate preliminary status update
        var limitVal = toolGr.getValue('u_lifecycle_limit') || toolGr.getValue('lifecycle_limit') || '10000';
        var limit = parseInt(limitVal, 10);
        var statusVal = toolGr.getValue('u_status') || toolGr.getValue('status');

        if (newTotal >= limit && statusVal === 'Available') {
            if (toolGr.isValidField('u_status')) {
                toolGr.setValue('u_status', 'Inspection Required');
            } else {
                toolGr.setValue('status', 'Inspection Required');
            }
        }

        // Commit update to database
        toolGr.update();
        gs.addInfoMessage("SUCCESS: Tool cycles updated to " + newTotal + " successfully!");
    } else {
        gs.addErrorMessage("ToolGuard Sync Error: Target Tool record not found.");
    }

})(current, previous);
